#include "tasks/ManualProcedureDomainReports.hpp"
#include <fstream>
#include <functional>
#include <iostream>
using namespace fathom;using namespace tasks::manual_procedure_graph_support;using V=json::Value;
std::size_t assertions{},refusals{},profiles{};
void check(bool b){++assertions;if(!b)throw std::runtime_error("ASSERT");}
const V& f(const V& x,const char* key){const auto* p=x.find(key);check(p!=nullptr);return *p;}
void refuse(const std::function<void()>& fn){try{fn();}catch(const std::runtime_error&){++refusals;return;}throw std::runtime_error("NO_REFUSAL");}
int main(int argc,char** argv){try{check(argc==2);std::ifstream in(argv[1]);check(in.good());std::string line;std::size_t rows{};while(std::getline(in,line)){const auto row=json::parse(line);const auto& g=f(f(row,"program"),"graph");for(const auto& n:f(g,"nodes").object()){if(const auto* op=n.second.find("computed_expected")){const auto& domain=f(f(g,"domains"),f(*op,"domain").string().c_str());for(const auto& record:domain.array()){const auto& choice=f(record,"selection");const auto result=projectClosedDomainReports(*op,choice,domain);check(result.resolved);for(const auto& field:f(*op,"fields").object()){const auto& values=f(result.values,field.first.c_str()).array();const auto& contacts=f(record,"contacts").array();check(values.size()==contacts.size());for(std::size_t i=0;i<values.size();++i)check(values[i]==f(contacts[i],field.second.string().c_str()));}++profiles;}
 auto unknown=f(domain.array().front(),"selection");for(auto& p:unknown.object())p.second=nullptr;const auto unresolved=projectClosedDomainReports(*op,unknown,domain);check(!unresolved.resolved&&unresolved.values.object().empty());auto bad=unknown;for(auto& p:bad.object())p.second=true;refuse([&]{(void)projectClosedDomainReports(*op,bad,domain);});auto duplicate=domain;duplicate.array().push_back(domain.array().front());refuse([&]{(void)projectClosedDomainReports(*op,f(domain.array().front(),"selection"),duplicate);});auto extra=*op;extra.object()["untrusted_default"]=true;refuse([&]{(void)projectClosedDomainReports(extra,f(domain.array().front(),"selection"),domain);});}}
++rows;
}
 const V contract=V::Object{{"steps",V::Array{V::Object{{"action","sustain_until_explicit_release"}},V::Object{{"action","explicit_learner_release"},{"duration_q",nullptr},{"automatically_timed",false}}}}};const V release=V::Object{{"original_contract_path",V::Array{"steps",V::fromInteger(1)}}};check(boundSourceAction(contract,release)==f(contract,"steps").array()[1]);for(const auto& index:V::Array{true,V::fromInteger(-1),V::fromInteger(2)})refuse([&]{(void)boundSourceAction(contract,V::Object{{"original_contract_path",V::Array{"steps",index}}});});check(rows==44&&profiles==100);std::cout<<"{\"outcome\":\"PASS\",\"rows\":44,\"profiles\":"<<profiles<<",\"assertions\":"<<assertions<<",\"refusals\":"<<refusals<<",\"owner_execution\":false,\"current224_mutated\":false}\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
